import{_ as p,a0 as i,w as s,s as l,ao as u,I as n,x as e,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"構建在開源之上的商業軟件市場持續成長 | LCTT x X-CMD","titleTemplate":false,"description":"構建在開源之上的商業軟件市場持續成長 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"構建在開源之上的商業軟件市場持續成長 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"構建在開源之上的商業軟件市場持續成長 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160301 The Evolving Market for Commercial Software Built On Open Source","title":"構建在開源之上的商業軟件市場持續成長","tag":"201607","desc":""},"relativePath":"201607/20160301 The Evolving Market for Commercial Software Built On Open Source.md","filePath":"[post].md"}'),m={name:"201607/20160301 The Evolving Market for Commercial Software Built On Open Source.md"};function f(d,t,T,w,C,S){const o=i("Link");return s(),l("div",null,[t[13]||(t[13]=u('<h1 id="構建在開源之上的商業軟件市場持續成長" tabindex="-1">構建在開源之上的商業軟件市場持續成長 <a class="header-anchor" href="#構建在開源之上的商業軟件市場持續成長" aria-label="Permalink to “構建在開源之上的商業軟件市場持續成長”">​</a></h1><p><img src="https://www.linux.com/images/stories/41373/Structure-event-photo.jpg" alt=""></p><p><em>與會者在 Structure 上聽取演講，Structure Data 2016 也將在 UCSF Mission Bay 會議中心舉辦。圖片來源：Structure Events。</em></p><p>如今真的很難低估開源項目對於企業軟件市場的影響；開源軟件的集成如此快速地形成了業界常態，我們沒能捕捉到轉折點也情有可原。</p><p>舉個例子，Hadoop，改變的不止是數據分析界，它引領了新一代數據公司，它們圍繞開源項目創造自己的軟件，按需調整和支持那些代碼，更像紅帽在上世紀 90 年代和本世紀早期擁抱 Linux 那樣。軟件越來越多地通過公有云交付，而不是運行在購買者自己的服務器，擁有了令人驚奇的操作靈活性，但同時也帶來了一些關於授權、支持以及價格之類的新問題。</p><p>我們多年來持續追蹤這個趨勢，這些話題充斥了我們的 Structure Data 會議，而今年的 Structure Data 2016 也不例外。三家圍繞 Hadoop 最重要的大數據公司——Hortonworks、Cloudera 和 MapR ——的 CEO 們將會共同討論它們是如何銷售他們圍繞開源項目的企業軟件和服務，獲利的同時回報社區項目。</p><p>以前在企業軟件上獲利是很容易的事情。一個客户購買了之後，企業供應商的一系列軟件就變成了收銀機，從維護合同和階段性升級中獲得近乎終生的收入，軟件也越來越難以被替代，因為它已經成為了客户的業務核心。客户抱怨這種綁定，但如果它們想提高工作隊伍的生產力也確實沒有多少選擇。</p><p>而現在的情況不再是這樣了。儘管無數的公司還陷於在他們的基礎設施上運行至關重要的巨型軟件包，新的項目被部署到使用開源技術的雲服務器上。這讓升級功能不再需要去掉大量軟件包再重新安裝別的，同時也讓公司按需付費，而不是為一堆永遠用不到的特性買單。</p><p>有很多客户想要利用開源項目的優勢，而又不想建立和支持一支工程師隊伍來調整那些開源項目以滿足自己的需求。這些客户願意為開源項目和在這之上的專有特性之間的差異付費。</p><p>這對於基礎設施相關的軟件來説格外正確。當然，你的客户們可以自己對項目進行調整，比如 Hadoop，Spark 或 Node.js，但付費可以幫助他們自定義地打包部署如今這些重要的開源技術，而不用自己幹這些活兒。只需看看 Structure Data 2016 的發言者就明白了，比如 Confluent（Kafka），Databricks（Spark），以及 Cloudera-Hortonworks-MapR（Hadoop）三人組。</p><p>當然還有一個值得提到的是在出錯的時候有個供應商給你背鍋。如果你的工程師弄糟了開源項目的實現，那你只能怪你自己了。但是如果你和一個願意提供服務級品質、能確保性能和正常運行時間指標的公司簽訂了合同，你實際上就是為得到支持、指導，以及有人背鍋而買單。</p><p>構建在開源之上的商業軟件市場的持續成長是我們在 Structure Data 上追蹤多年的內容，如果這個話題正合你意，我們鼓勵你加入我們，在舊金山，3 月 9 日和 10 日。</p><hr>',13)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.linux.com/news/enterprise/cloud-computing/889564-the-evolving-market-for-commercial-software-built-on-open-source-"},{default:a(()=>[...t[0]||(t[0]=[e("https://www.linux.com/news/enterprise/cloud-computing/889564-the-evolving-market-for-commercial-software-built-on-open-source-",-1)])]),_:1})]),n("p",null,[t[5]||(t[5]=e("作者：",-1)),r(o,{href:"https://www.linux.com/community/forums/person/70513"},{default:a(()=>[...t[2]||(t[2]=[e("Tom Krazit",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),r(o,{href:"https://github.com/alim0x"},{default:a(()=>[...t[3]||(t[3]=[e("alim0x",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:a(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:a(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const k=p(m,[["render",f]]);export{v as __pageData,k as default};
